 for(i=0;i<5;++i){uint32_t x=i<2?0:i-1;src[i]=(dmg_source_spec){sizeof(dmg_source_spec),DMG_ABI_VERSION,DMG_INPUT_RAW_DEX,0,b[x],(uint64_t)n[x],slots[i],"string",NULL};}
 CHECK(dmg_snapshot_open_sources(engine,src,5,&so,&snap,&err)==DMG_OK);CHECK(dmg_query_compile_json(engine,(const uint8_t*)text,strlen(text),&query,&err)==DMG_OK);
 fast=(dmg_result*)(uintptr_t)1;CHECK(dmg_query_execute_reverse_target_v1(snap,query,&opt,&fast,&err)==DMG_UNSUPPORTED&&fast==NULL);CHECK(strcmp(err.message,"reverse target join requires direct invoke and method reference scans")==0);fast=(dmg_result*)(uintptr_t)1;CHECK(dmg_query_execute_reverse_field_target_v1(snap,query,&opt,&fast,&err)==DMG_UNSUPPORTED&&fast==NULL);CHECK(strcmp(err.message,"reverse field target join requires direct field use and field reference scans")==0);
 CHECK(dmg_query_execute(snap,query,&plain,&err)==DMG_OK&&plain);CHECK(dmg_snapshot_reverse_profile_v1(snap,&profile,sizeof(profile))==DMG_OK&&profile.builds==0);CHECK(dmg_query_execute_reverse_string_target_v1(snap,query,&opt,&fast,&err)==DMG_OK&&fast);CHECK(dmg_result_get_relation_info_v2(plain,&p,sizeof(p))==DMG_OK&&dmg_result_get_relation_info_v2(fast,&q,sizeof(q))==DMG_OK&&p.candidates_count==9&&q.candidates_count==9);
 for(i=0;i<9;++i){dmg_value_row_v2 x={0},y={0};dmg_relation_link_v2 l={0};dmg_source_info origin={0};CHECK(dmg_result_get_value_v2(plain,i,&x,sizeof(x))==DMG_OK&&dmg_result_get_value_v2(fast,i,&y,sizeof(y))==DMG_OK&&x.kind==DMG_VALUE_USE&&y.kind==DMG_VALUE_USE);CHECK(x.use.source_index==y.use.source_index&&x.use.dex_pc==y.use.dex_pc&&x.use.opcode==y.use.opcode&&x.use.target_index==y.use.target_index&&y.use.target_domain==DMG_TARGET_STRING_VALUE);CHECK(dmg_result_get_link_v2(fast,i,0,&l,sizeof(l))==DMG_OK&&l.left.source_index==l.right.source_index&&l.left.source_index==y.use.source_index&&l.right.local_index==y.use.target_index);CHECK(dmg_result_get_origin(fast,i,&origin)==DMG_OK&&origin.source_index==y.use.source_index);}
 CHECK(dmg_snapshot_reverse_profile_v1(snap,&profile,sizeof(profile))==DMG_OK&&profile.builds==5&&profile.reuses>0);dmg_result_release(plain);dmg_query_release(query);dmg_snapshot_release(snap);dmg_engine_release(engine);for(i=0;i<4;++i)free(b[i]);{dmg_value_row_v2 row={0};CHECK(dmg_result_get_value_v2(fast,0,&row,sizeof(row))==DMG_OK&&row.kind==DMG_VALUE_USE&&row.use.dex_pc==0);}dmg_result_release(fast);puts("PASS real C string reverse consumer and retained result");return 0;
